responses.body:
body {
  padding: 0;
  margin: 0;
  background-color: #ffffff;
  text-align: left;
  color: #000000;
}

.body_error {
  background-color: black;
  color: white;
}

.body_error a:link {
  color: #00DED1;
}

.body_error a:visited {
  color: #00DED1;
}

.body_error a:active {
  color: #FFB372;
}

.stripe {
  display: block;
  background-color: #01d4ff;
  border: 0;
  outline: 0;
  height: 25px;
  width: 100%;
  padding: 0px;
  margin:  0;
  display: block;
  padding-right:10px;
}

.main {
  font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
  font-weight: 900;
  margin: 20px;
  padding: 10px;
  text-align: center;
}

.outer {
  display:  table;
  position: absolute;
  height:   100%;
  width:    100%;
}

.middle {
  display: table-cell;
  vertical-align: middle;
}

.footer {
  position:      fixed;
  left:          0px;
  bottom:        0px;
  color:         #CCCCCC;
  font-family:   'Helvetica Neue', Helvetica, Arial, sans-serif;
  font-style:    italic;
  text-align:    left;
  margin-left:   10px;
  margin-bottom: 10px;
  padding-right:  10px;
  width:         100%;
}

.footer a:link    { color: #CCCCCC; }
.footer a:visited { color: #CCCCCC; }
.footer a:hover   { color: #CCCCCC; }
.footer a:active  { color: #CCCCCC; }

.tips_main {
  font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
  font-size:     12pt;
  margin:        20px;
  text-align:    left;
  height:        100%;
  line-height:   150%;
}

.tips_main h1 {
  font-weight: 900;
  font-size:   24pt;
}

.tips_main h2 {
  font-weight: 900;
  font-size:   18pt;
}

.tips_main p {
  margin-left: 40px;
}

.tips_main ul {
  list-style-type: none;
  padding-top: 10px;
  padding-left: 20px;
  padding-right: 20px;
  padding-bottom: 20px;
}

.tips_main li {
  margin-bottom: 30px;
}

.tips_main img {
  margin-top: 15px;
  margin-bottom: 15px;
  margin-left: 40px;
  border-width: 2px;
  border-color: black;
  border-style: solid;
}

.tips_footer {
  margin-top:  50px;
  color:       #CCCCCC;
  font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
  font-style:  italic;
  text-align:  left;
}
input[type=text] {
  border-radius: 50px; 
  padding: 5px;
  text-align: center;
  -webkit-transition: all 0.30s ease-in-out;
  -moz-transition: all 0.30s ease-in-out;
  -ms-transition: all 0.30s ease-in-out;
  -o-transition: all 0.30s ease-in-out;
  outline: none;
}

.viva_button_disabled {
  -webkit-transition: all 0.30s ease-in-out;
  -moz-transition:    all 0.30s ease-in-out;
  -ms-transition:     all 0.30s ease-in-out;
  -o-transition:      all 0.30s ease-in-out;
  margin-right:auto;
  margin-left:auto;
  margin-top: 30px;
  border-radius: 50px;
  padding: 5px;
  text-align: center;
  border-width: 4px;
  border-color: #CCCCCC;
  border-style: solid;
  background-color: #AAAAAA;
  width: 200px;
  color: #EEEEEE;
  font-weight: 200;
  font-size: 24px; 
}

.viva_button_enabled {
  -webkit-transition: all 0.30s ease-in-out;
  -moz-transition:    all 0.30s ease-in-out;
  -ms-transition:     all 0.30s ease-in-out;
  -o-transition:      all 0.30s ease-in-out;
  margin-right:       auto;
  margin-left:        auto;
  margin-top:         30px;
  border-radius:      50px;
  padding:            5px;
  text-align:         center;
  border-width:       4px;
  border-color:       #FEEB31;
  border-style:       solid;
  background-color:   #FFFFFF;
  width:              200px;
  color:              #000000;
  font-weight:        900;
  font-size:          24px; 
  text-decoration:    none;
  box-shadow:         0 0 0 5px #FEA600, 0 0 0 10px #FD2637;
  cursor:             pointer;
}

.viva_button_enabled:active {
  border-color:     #B3D4E7;
  box-shadow:       0 0 0 5px #57ACD6, 0 0 0 10px #004C8D;
  color:            white;
  background:       black;
}

@media only screen and (min-width: 0px) {
  .main-text {
    font-size: 34px;
    text-align: center;
    line-height:60px;
  }
  input {
    font-size:34px;
  }
}

@media only screen and (min-width: 700px) {
  .main-text {
    font-size: 36px;
  }
  input {
    font-size:36px;
  }
}

@media only screen and (min-width: 750px) {
  .main-text {
    font-size: 38px;
  }
  input {
    font-size:38px;
  }
}
@media only screen and (min-width: 850px) {
  .main-text {
    font-size: 44px;
  }
  input {
    font-size:44px;
  }
}
@media only screen and (min-width: 950px) {
  .main-text {
    font-size: 48px;
  }
  input {
    font-size:48px;
  }
}
@media only screen and (min-width: 1050px) {
  .main-text {
    font-size: 52px;
  }
  input {
    font-size:52px;
  }
}

input {
  font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;
  font-weight: 900;
}

